INSERT INTO courses(slug,code,name,short_name,domain,summary,detailed_description,technologies,primary_stack,target_degrees,available_timings,capstone,curriculum,featured,status,created_at) VALUES ('modern-seo-organic-growth','SEO','Search Engine Optimization (SEO) & Organic Growth','Modern SEO Masterclass','fullstack','Master end-to-end modern SEO from technical audits and semantic keyword research to AI-driven on-page optimization, content strategy, programmatic SEO, and authoritative backlink acquisition.','This industrial, hands-on Search Engine Optimization (SEO) program equips learners with actionable skills to rank web properties on Google and leading search engines. Covering the spectrum from foundational search engine mechanics to advanced technical optimization, students will learn Core Web Vitals diagnostics, crawl budget management, structured schema data, keyword clustering, and intent-based content creation. The curriculum also dives deep into enterprise-grade analytics (Google Search Console & Google Analytics 4), competitor intelligence using industry-standard tools (SEMrush & Ahrefs), local search (Google Business Profile), e-commerce SEO, and Generative Engine Optimization (GEO) for AI search summaries (ChatGPT Search, Perplexity, and Google AI Overviews).','["Google Search Console", "Google Analytics 4", "Ahrefs", "SEMrush", "Schema.org", "Looker Studio"]'::jsonb,'["Technical SEO", "On-Page SEO", "Off-Page SEO", "Content & Semantic Optimization", "Local SEO", "GEO & AI Search Strategy"]'::jsonb,'["BBA", "MBA", "B.Com", "BCA", "B.Tech / B.E.", "B.A. (Mass Communication / Journalism)", "MCA", "Any Graduate / Digital Marketing Aspirant"]'::jsonb,'["07:30_AM", "02:00_PM", "06:00_PM", "08:30_PM"]'::jsonb,'{"title": null, "problemStatement": null, "architecture": null, "modules": [], "deploymentTarget": "Production", "repositoryStructure": "monorepo", "academicDocReady": true}'::jsonb,'{"1D": [], "10D": [], "20D": [], "30D": [], "45D": []}'::jsonb,false,'active','2026-10-24 05:25:41'::timestamptz) ON CONFLICT (slug) DO NOTHING;
